#include "stdafx.h"#include "ModbusTcpServerImpl.h"#ifdef _MANAGED#pragma managed(push, off)#endifHINSTANCE g_hInst = 0;BOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){  switch (ul_reason_for_call)  {  case DLL_PROCESS_ATTACH:    g_hInst = hModule;  case DLL_THREAD_ATTACH:  case DLL_THREAD_DETACH:  case DLL_PROCESS_DETACH:    break;  }  return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endifextern "C" Q_DECL_DLLEXPORT      IBaseModel* CreateObject(LPCTSTR ObjName ){  return new KModbusTcpServerImpl( (LPSTR)ObjName);}